probes.source:
module child(input bit a, b, output bit y, c);
  always_comb begin y = 0; if (a) y = 1; c = b; end
endmodule
module Top;
  bit a, b, y6, c6;
  int n6;
  child u(.a(a), .b(b), .y(y6), .c(c6));
  initial forever begin @(y6); n6++; end
  initial begin #1 a = 1; #1 b = 1; #1 b = 0; #1 $display("child=%0d", n6); $finish; end
endmodule
